const app=document.querySelector('#app');
const stages=[['같은 수씩 묶기','간식 봉지에 똑같이 담아 봐요.'],['그림을 식으로 바꾸기','묶음 그림을 덧셈과 곱셈으로 나타내요.'],['한 묶음씩 늘리기','묶음이 늘 때 답이 어떻게 바뀔까요?'],['배열을 돌려 보기','가로와 세로를 바꾸어 살펴봐요.'],['아는 답으로 새 답 찾기','더하고, 빼고, 두 배로 만들어 봐요.'],['가리고 떠올리기','답을 떠올린 뒤 직접 확인해요.'],['생활 속에서 써 보기','주변에서 곱셈 문제를 찾아요.'],['섞어서 다시 꺼내기','배운 식을 조금씩 다시 만나 봐요.']];
const rounds=[{n:2,g:3,icon:'🍪',item:'간식',unit:'개',box:'봉지',type:'따라 하기'},{n:3,g:4,icon:'🍪',item:'간식',unit:'개',box:'봉지',type:'혼자 하기',assess:true},{n:2,g:4,icon:'🌷',item:'꽃',unit:'송이',box:'꽃다발',type:'그림 읽기',read:true,assess:true},{n:4,g:3,icon:'✏️',item:'색연필',unit:'자루',box:'통',type:'생활 문제',assess:true},{n:2,g:4,icon:'🍪',item:'간식',unit:'개',box:'봉지',type:'섞어 보기 · 첫 번째'},{n:4,g:2,icon:'🍪',item:'간식',unit:'개',box:'봉지',type:'섞어 보기 · 두 번째'}];
let r=0,phase='fill',bags=[],q=0,count=0,answers=[],score=0,clean=true,complete=false,view='home',message='',hint='';
const current=()=>rounds[r];
function home(){view='home';app.innerHTML=`<span class="pill">나의 구구단 탐험</span><h1>한 걸음씩, 구구단을 알아봐요</h1><p class="lead">묶어 보고, 답을 만들고, 스스로 떠올려 봐요.</p><div class="steps">${stages.map((s,i)=>`<button class="step ${i<8?'active':''}" data-stage="${i}"><span class="num">STEP ${String(i+1).padStart(2,'0')}</span><strong>${s[0]}</strong><small>${i===0?(complete?'✓ 완료 · 다시 해 보기':'간식 봉지 만들기 →'):s[1]}</small></button>`).join('')}</div><p class="sub"><b>1~8단계</b>를 모두 만나 볼 수 있어요. 배운 식은 마지막 단계에서 섞어 복습해요.</p><details><summary>함께하는 어른에게</summary><p>속도를 재지 않고, 한 묶음에 몇 개씩 있는지와 묶음이 몇 개인지를 구별하도록 도와주세요. 1단계에는 곱셈식을 표시하지 않습니다.</p><p>연습 뒤 세 가지 상황에서 ‘몇 개씩’, ‘몇 묶음’, ‘모두 몇 개’를 확인합니다. 세 질문에 첫 시도로 답한 상황이 3개 중 2개 이상이면 다음 단계로 나아갈 준비가 된 것으로 안내합니다. 다시 세어 보고 고칠 기회는 언제나 있습니다. 5~8단계의 카드와 복습 기록은 이 브라우저에 저장됩니다.</p></details>`;app.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const i=+b.dataset.stage;if(i===0){r=0;score=0;startRound()}else if(i===1){start2()}else if(i===2){start3()}else if(i===3){start4()}else if(i===4){start5()}else if(i===5){start6()}else if(i===6){start7()}else if(i===7){start8()}else{view='detail';app.innerHTML=`<button onclick="home()">← 전체 단계</button><div class="activity" style="margin-top:20px"><span class="pill">${i+1}단계 · 배울 내용</span><h1>${stages[i][0]}</h1><p>${stages[i][1]}</p><p class="small">이 단계의 놀이 활동은 아직 준비 중이에요.</p><button class="primary" onclick="r=0;score=0;startRound()">1단계 놀이하기</button></div>`}})}
function startRound(){view='activity';phase=current().read?'quiz':'fill';bags=Array(current().g).fill(current().read?current().n:0);q=0;count=0;answers=[];clean=true;hint='';message=current().read?'그림을 보고 몇 개씩, 몇 묶음인지 찾아봐요.':r===0?'봉지 아래 +를 누르면 간식이 하나 들어가요. 많이 담았으면 −로 꺼내요.':'모든 묶음에 같은 수씩 담아 주세요.';render()}
function bagHTML(d){return bags.map((v,i)=>`<div class="bag ${hint==='one'&&i===0||hint==='all'?'highlight':''} ${phase==='count'&&i<count?'counted':''}" id="bag${i}"><span class="baglabel">${d.box} ${i+1}</span><div class="items" aria-label="${d.item} ${v}${d.unit}">${Array(v).fill(`<span aria-hidden="true">${d.icon}</span>`).join('')||'<span class="small">비어 있어요</span>'}</div>${phase==='fill'?`<div class="controls"><button aria-label="${i+1}번 ${d.box}에서 하나 꺼내기" data-bag="${i}" data-delta="-1" ${v===0?'disabled':''}>−</button><button aria-label="${i+1}번 ${d.box}에 하나 담기" data-bag="${i}" data-delta="1" ${v>=6?'disabled':''}>+</button></div>`:phase==='count'?`<button data-count="${i}" ${i!==count?'disabled':''}>${i<count?'✓ 셌어요':'눌러서 세기'}</button>`:''}${phase==='fill'&&hint==='counts'?`<b>${v}${d.unit}</b>`:''}</div>`).join('')}
function render(){const d=current();let title=phase==='fill'?`${d.box}마다 <em>${d.n}${d.unit}씩</em> 담아 주세요.`:phase==='quiz'?q===0?`한 ${d.box}에 <em>몇 ${d.unit}씩</em> 있나요?`:q===1?`<em>${d.box}</em>${d.box==='통'?'은':'는'} 모두 몇 개인가요?`:`${d.item}${d.item==='꽃'?'은':'은'} 모두 <em>몇 ${d.unit}</em>인가요?`:phase==='count'?'묶음을 하나씩 누르며 세어 봐요.':'몇 개씩, 몇 묶음인지 찾았어요!';app.innerHTML=`<div class="topline"><span class="pill">1단계 · 같은 수씩 묶기</span><span class="small">활동 ${r+1} / ${rounds.length}</span></div><section class="activity"><div class="track" aria-label="전체 6개 활동 중 ${r+1}번째">${rounds.map((_,i)=>`<i class="${i<=r?'done':''}"></i>`).join('')}</div><span class="small">${d.type}</span><h1 class="instruction">${title}</h1>${phase==='fill'?`<p>${d.box} ${d.g}개에 ${d.item}${d.item==='꽃'?'을':'을'} 똑같이 나눠 담아 주세요.</p>`:''}<div class="workspace"><div class="bags">${bagHTML(d)}</div>${phase==='quiz'?`<div class="choices" aria-label="답 고르기">${(q===2?[...new Set([d.n*d.g-d.n,d.n*d.g,d.n*d.g+d.n])]:[1,2,3,4,5]).map(n=>`<button data-answer="${n}">${n}</button>`).join('')}</div>`:''}${phase==='count'?`<div class="countline" aria-live="polite">${Array.from({length:count},(_,i)=>(i+1)*d.n).join(' → ')}</div>`:''}</div><div class="feedback ${phase==='done'?'good':''}" role="status">${message}</div><div class="actions">${phase==='fill'?'<button onclick="bags.fill(0);hint=\'\';message=\'다시 차근차근 담아 봐요.\';render()">다시 담기</button><button class="primary" onclick="checkBags()">똑같이 담았어요</button>':phase==='quiz'?'<button onclick="hint=q===0?\'one\':\'all\';message=\'그림을 손가락으로 짚으며 세어 봐요.\';clean=false;render()">그림 힌트 보기</button>':phase==='count'?`<button class="primary" onclick="phase='quiz';q=2;message='방금 센 전체 개수를 골라 봐요.';render()" ${count<d.g?'disabled':''}>모두 몇 개인지 답하기</button>`:`<button class="primary" onclick="nextRound()">${r===5?'1단계 마무리':'다음 활동 →'}</button>`}</div></section><p class="footer">천천히 해도 괜찮아요. 그림을 보며 다시 생각해 봐요.</p>`;app.querySelectorAll('[data-bag]').forEach(b=>b.onclick=()=>{bags[+b.dataset.bag]+=+b.dataset.delta;render()});app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));app.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{count++;render()})}
function checkBags(){const d=current();if(bags.every(v=>v===d.n)){phase='quiz';q=0;hint='';message='모든 묶음에 똑같이 담았네요! 그림을 보고 답해 봐요.'}else{hint='counts';message=`모든 ${d.box}에 ${d.n}${d.unit}씩 들어갔을까? 묶음마다 개수를 보고 고쳐 봐요.`}render()}
function answer(n){const d=current(),expected=[d.n,d.g,d.n*d.g][q];if(n!==expected){clean=false;hint=q===0?'one':'all';message=q===0?`강조된 한 ${d.box} 안에 몇 ${d.unit} 있는지 다시 세어 봐요.`:q===1?`${d.box} 하나를 한 묶음으로 세어 봐요. 안에 든 ${d.item} 개수와 구별해요.`:'묶음을 하나씩 누르면서 전체 개수를 다시 세어 봐요.';if(q===2){phase='count';count=0}render();return}answers[q]=n;hint='';if(q<1){q++;message=`맞아요! 한 ${d.box}에 ${d.n}${d.unit}씩 있어요.`}else if(q===1){if(r===0){phase='count';count=0;message='이번에는 전체 개수를 함께 세어 봐요.'}else{q=2;message='눈으로 하나씩 세어도 좋고, 묶음별로 세어도 좋아요.'}}else{phase='done';if(d.assess&&clean)score++;message=`${d.n}${d.unit}씩 ${d.g}묶음, 모두 ${d.n*d.g}${d.unit}예요.${r===5?' 앞에서는 2개씩 4묶음, 이번에는 4개씩 2묶음을 만들었어요.':''}`}render()}
function nextRound(){if(r<5){r++;startRound()}else{complete=score>=2;view='finish';app.innerHTML=`<section class="activity finish"><div class="star" aria-hidden="true">${complete?'🌟':'🌱'}</div><span class="pill">1단계 활동 마무리</span><h1>${complete?'같은 수씩 묶을 수 있어요!':'묶음을 차근차근 살펴봤어요!'}</h1><p>${complete?'몇 개씩, 몇 묶음인지 잘 구별했어요.<br>2단계에서는 이 그림을 식으로 바꾸어 볼 거예요.':'그림을 보며 고치고 답을 찾아냈어요.<br>한 번 더 담아 보며 몇 개씩, 몇 묶음인지 익혀 봐요.'}</p><p class="small">세 가지 확인 상황 중 ${score}개를 도움 없이 첫 시도에 해결했어요.<br>이제 2단계에서 그림에 식을 붙여 볼 수 있어요.</p><div class="choices" style="justify-content:center"><button class="primary" onclick="start2()">2단계 식 붙이기</button><button onclick="home()">전체 단계 보기</button><button onclick="r=0;score=0;startRound()">한 번 더 해 보기</button></div></section>`}}
document.querySelector('#homeBtn').onclick=home;home();
